with open('/home/bob/books/_archived_20260507_123632/FG/First_Generation/First_Generation_Manuscript.md') as f:
    current = f.read()

with open('/home/bob/books/_archived_20260507_123632/FG/First_Generation/FIRST_GENERATION_COMPLETE.md') as f:
    complete = f.read()

# Check chapter 10 word counts
import re

def get_chapter_wordcount(content, ch_num):
    pattern = rf'Chapter {ch_num:02d}[^~]*?(?=Chapter {ch_num+1:02d}|$)'
    if ch_num < 10:
        pattern = rf'Chapter\s+0?{ch_num}\s*[—–-]+\s*[^~]*?(?=Chapter\s+0?{ch_num+1}\s*[—–-]|$)'
    # Simpler approach
    lines = content.split('\n')
    in_chapter = False
    words = 0
    for line in lines:
        if re.match(rf'^#{{1,3}}\s+Chapter\s+0?{ch_num}\b', line):
            in_chapter = True
            continue
        if re.match(rf'^#{{1,3}}\s+Chapter\s+0?{ch_num+1}\b', line):
            break
        if in_chapter and line.strip():
            words += len(line.split())
    return words

for ch in range(1, 16):
    curr_wc = get_chapter_wordcount(current, ch) if ch <= 10 else 0
    if ch <= 14:
        comp_wc = get_chapter_wordcount(complete, ch)
    else:
        comp_wc = 0
    marker = "✅ EXPANDED" if curr_wc > 300 else "📄 STUB"
    print(f"  Ch {ch:2d}: working={curr_wc:6d}w | complete={comp_wc:6d}w {marker}")

# Also check Ch 11 and 14 in the working (current) manuscript
for ch in [11, 14]:
    wc = get_chapter_wordcount(current, ch)
    print(f"  Ch {ch:2d}: working={wc:6d}w | (these were Deep Work'd)")"}

